const SOLO = []
const PHRASES = { A: THEME_A, B: THEME_B, BRIDGE, REST, SOLO }

// who plays which phrase: [start beat, phrase, transpose, stretch (2 = half speed)]
const LEAD = [[0,"REST",0,1],[16,"A",0,1],[48,"A",0,1],[80,"REST",0,1],[112,"A",0,1],[128,"A",2,1],[160,"A",2,1],[192,"REST",0,1],[224,"A",0,2]]
const LEAD2 = [[0,"REST",0,1],[16,"REST",0,1],[80,"B",0,1],[112,"REST",0,1],[128,"REST",0,1],[192,"BRIDGE",0,1],[208,"BRIDGE",0,1],[224,"REST",0,1]]
const COUNTER = [[0,"REST",0,1],[16,"REST",0,1],[80,"REST",0,1],[112,"REST",0,1],[128,"HARMONY",0,1],[192,"REST",0,1],[224,"REST",0,1]]
// the note of a voice at x → { n, d, τ, u, at } or null
function voiceAt(plan, x) {
  if (x >= END) return null
  let row = null
  for (const r of plan) if (r[0] <= x) row = r
  if (!row) return null
  const [s, name, tr, k] = row, m = notesAt(PHRASES[name] ?? REST, (x - s) / k)
  return m && { n: m.n + tr, d: m.d * k, τ: m.τ * k, u: m.u, at: s + m.at * k }
}
const leadAt = x => voiceAt(LEAD, x)
const lead2At = x => voiceAt(LEAD2, x)
// the counter-voice: HARMONY = the highest chord tone at least a third below the lead (computed from
// the chords); CANON = the lead itself two beats later, an octave down
const counterAt = x => {
  let row = null
  for (const r of COUNTER) if (r[0] <= x) row = r
  if (!row || x >= END) return null
  if (row[1] === 'CANON') {
    const m = x - 2 >= row[0] ? leadAt(x - 2) : null
    return m && { ...m, n: m.n - 12, at: m.at + 2 }
  }
  if (row[1] !== 'HARMONY') return null
  const m = leadAt(x), c = chordAt(x)
  if (!m || !c) return null
  const pcs = c[3].map(n => mod(n, 12))
  for (let n = m.n - 3; n > m.n - 12; n--) if (pcs.includes(mod(n + 60, 12))) return { ...m, n }
  return null
}

// ---- squarelead2 -------------------------------------------------------------------------------
const track0 = {
  color: '#9bf6ff',
  graph: x => { const m = leadAt(x); return m ? 1.1 + (m.n + 5) * 0.0559 : null },
  midi: x => { const m = leadAt(x); return m && m.u < 0.92 ? [60 + m.n] : [] },
  formula: ["y = \\Rev\\Big[a(\\tau)\\sum_{k} A_k\\sin\\big(2\\pi k\\!\\int\\! f\\,dt + \\varphi_k\\big)\\Big],\\quad A_k = \\frac{B(kf)}{k^{p}}\\ \\text{— гармоники по спектру инструмента: наклон источника и резонансы корпуса}","f = f_0\\,2^{(v(\\tau)\\sin 2\\pi f_v t - s\\,e^{-\\tau/45\\text{мс}})/1200}\\ \\text{— вибрато приходит позже, подъезд к ноте, легато — глиссандо}"],
  audio({ bpm }) {
    const sec = 60 / bpm, a = soloist('square', { vib: 1, glide: 0.04, scoop: 0, accent: 0, seed: 5 }), verb = hall({ decay: 2.4, wet: 0.28 }), echo = delay({ time: sec * 0.75, feedback: 0.3, wet: 0.2 })
    let n = 0, vel = 0.8
    return x => {
      const m = leadAt(x)
      if (m) { n = m.n; vel = 0.6 + 0.07 * Math.max(0, energy(x)) + 0.16 * hash(floor(2 * m.at), 5) + (mod(m.at, 4) === 0 ? 0.06 : 0) }
      const on = !!m && m.u < 0.94, f = hz(n + 0, C4)
      const y = 2.6 * (a(f, on, vel))
      return verb(...echo(...pan(y, 0.12)))
    }
  },
}

